package com.eventhub.repository; import com.eventhub.entity.Feedback; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface FeedbackRepository extends JpaRepository<Feedback,Long>{boolean existsByEventIdAndUserId(Long eventId,Long userId); Page<Feedback> findByEventIdOrderByCreatedAtDesc(Long eventId,Pageable p); @Query("select coalesce(avg(f.rating),0) from Feedback f where f.event.id=:eventId") double averageForEvent(@Param("eventId") Long eventId); long countByEventId(Long eventId);}
